import * as THREE from 'three/webgpu';
import * as tsl from 'three/tsl';
import { gsap } from 'gsap';
import primitives from '@/primitives';
import text from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // ---------- Prism ----------
  const side = 1.2;
  const radius = side / Math.sqrt(3);
  const length = 1.8;
  const prismGeometry = new THREE.CylinderGeometry(radius, radius, length, 3);
  prismGeometry.rotateX(Math.PI / 2); // make axis horizontal (X)

  const prismMaterial = new THREE.MeshPhysicalMaterial({ color: 0x16161d, side: THREE.DoubleSide });
  prismMaterial.transmissionNode = new tsl.TransmissionNode(1.0);
  prismMaterial.thicknessNode = new tsl.ThicknessNode(0.9);
  prismMaterial.iorNode = new tsl.IORNode(1.55);
  prismMaterial.dispersionNode = new tsl.DispersionNode(0.18);
  prismMaterial.iridescenceNode = new tsl.IridescenceNode(1.0);
  prismMaterial.iridescenceIORNode = new tsl.IridescenceIORNode(1.3);
  prismMaterial.iridescenceThicknessRangeNode = new tsl.IridescenceThicknessRangeNode(new THREE.Vector2(120, 480));
  prismMaterial.roughnessNode = new tsl.RoughnessNode(0.08);
  prismMaterial.clearcoatNode = new tsl.ClearcoatNode(0.25);
  prismMaterial.clearcoatRoughnessNode = new tsl.ClearcoatRoughnessNode(0.1);
  prismMaterial.attenuationColorNode = new tsl.AttenuationColorNode(new THREE.Color('#e8ecf2'));
  prismMaterial.attenuationDistanceNode = new tsl.AttenuationDistanceNode(2.5);

  const prism = new THREE.Mesh(prismGeometry, prismMaterial);
  prism.rotation.z = THREE.MathUtils.degToRad(12);
  prism.rotation.y = THREE.MathUtils.degToRad(20);
  group.add(prism);

  // ---------- Emissive Core ----------
  const coreGeometry = new THREE.OctahedronGeometry(0.35);
  const coreMaterial = new THREE.MeshPhysicalMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 2.2,
    side: THREE.DoubleSide
  });
  const core = new THREE.Mesh(coreGeometry, coreMaterial);
  core.position.set(0, 0, 0);
  group.add(core);

  // ---------- Back Rim Light ----------
  const rimLight = new THREE.DirectionalLight(0xffffff, 1.5);
  rimLight.position.set(-2, 1, -2); // behind‑left
  rimLight.target = prism;
  group.add(rimLight);
  group.add(rimLight.target);

  // ---------- Caustic Streak ----------
  const streakGeometry = new THREE.PlaneGeometry(2.4, 0.5);
  const uvNode = new tsl.UVNode();

  // Linear gradient across X
  const colorA = new tsl.ColorNode('#ff2a38');
  const colorB = new tsl.ColorNode('#e8ecf2');
  const colorC = new tsl.ColorNode('#9fb0c4');

  const gradientNode = tsl.mix(
    tsl.mix(colorA, colorB, tsl.smoothstep(uvNode.x, 0.2, 0.5)),
    colorC,
    tsl.smoothstep(uvNode.x, 0.5, 0.8)
  );

  const streakMaterial = new THREE.MeshBasicNodeMaterial();
  streakMaterial.colorNode = gradientNode;
  streakMaterial.transparent = true;
  streakMaterial.opacityNode = new tsl.FloatNode(0.35);
  const streak = new THREE.Mesh(streakGeometry, streakMaterial);
  streak.rotation.x = -Math.PI / 2; // lay flat on floor
  streak.position.set(0, -1.1, 0);
  group.add(streak);

  // ---------- Text ----------
  const headlineOpts = {
    fontFamily: 'Lora',
    fontSize: 68,
    fontWeight: 600,
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: '#e8ecf2',
    atlasIndex: 0,
    sourceRect: [0, 0, 512, 320]
  };
  const captionOpts = {
    fontFamily: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    letterSpacing: 0.08,
    lineHeight: 1.4,
    color: '#e8ecf2',
    atlasIndex: 0,
    sourceRect: [0, 0, 512, 320]
  };

  const headlineMesh = ctx.fontAtlas.createMesh('Light, machined.', headlineOpts);
  const captionMesh = ctx.fontAtlas.createMesh('SAPPHIRE OVER DIAL / ZERO DISTORTION', captionOpts);

  headlineMesh.position.set(0, -1.75, 0);
  captionMesh.position.set(0, -2.25, 0);

  group.add(headlineMesh);
  group.add(captionMesh);

  // ---------- Cinematic Primitive ----------
  if (ctx.primitives && typeof ctx.primitives['depth-rotate'] === 'function') {
    ctx.primitives['depth-rotate'](group, { maxDeg: 10 });
  }

  // ---------- Cleanup ----------
  const disposables = [
    prismGeometry,
    coreGeometry,
    streakGeometry,
    prismMaterial,
    coreMaterial,
    streakMaterial
  ];
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    disposables.forEach(d => d.dispose?.());
    gsap.globalTimeline.clear();
  };

  return group;
}
